import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addHours_TriageGen1Test {







    @Test
    public void testAddHours_OverflowDays() {
        // Test that adding hours rolls over the day correctly
        // 2023-01-01T22:00:00 + 4 hours = 2023-01-02T02:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 22, 0, 0, 0);
        dt.addHours(4);
        assertEquals(2, dt.getDayOfMonth());
        assertEquals(2, dt.getHourOfDay());
    }


}

