public class MutableDateTime_addHours_TriageGen1Test {









    @Test
    public void testAddHours_LargeValue() {
        // Test adding a large number of hours (e.g., 48 hours = 2 days)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addHours(48);
        assertEquals(3, dt.getDayOfMonth());
        assertEquals(10, dt.getHourOfDay());
    }
